commands=[]
def command(id,lesson,title,environment,code,situation,result,warning,tokens):
    commands.append(dict(id=id,lesson=lesson,title=title,environment=environment,code=code,situation=situation,result=result,warning=warning,tokens=[dict(token=t,meaning=m) for t,m in tokens]))

command('tr-case','shell','Đưa chữ hoa về chữ thường','Bash · Linux / WSL',"tr '[:upper:]' '[:lower:]' < article.txt > lowercase.txt",'Cần chuẩn hóa chữ hoa/thường trước khi đếm tần suất trong bài thay thế đơn bảng.','lowercase.txt chứa kết quả chữ thường; article.txt được đọc qua stdin.','Lớp ký tự phụ thuộc locale. Không đọc và ghi cùng tệp.',[
 ('tr','Công cụ ánh xạ hoặc xóa từng ký tự, không thay cả từ.'),("'[:upper:]'",'Tập ký tự chữ hoa, được đặt trong nháy để shell không tự mở rộng.'),("'[:lower:]'",'Tập chữ thường tương ứng làm ánh xạ đích.'),('< article.txt','Shell lấy nội dung article.txt vào stdin.'),('> lowercase.txt','Shell ghi stdout vào lowercase.txt và ghi đè nếu đã tồn tại.')])
command('tr-filter','shell','Giữ chữ ASCII, xuống dòng và khoảng trắng','Bash · Linux / WSL',r"tr -cd 'a-z\n ' < lowercase.txt > plaintext.txt",'Bài tập tiếng Anh cần bỏ số/ký hiệu trước khi đếm tần suất.','Các ký tự ngoài a-z, newline và space bị xóa.','Làm mất dữ liệu tiếng Việt. Dấu > có thể ghi đè.',[
 ('tr','Xử lý ký tự từ luồng đầu vào.'),('-c','Chọn phần bù của tập ký tự đã nêu.'),('-d','Xóa ký tự được chọn; kết hợp -c thành xóa phần ngoài tập.'),(r"'a-z\n '",'Tập cho phép gồm chữ thường ASCII, newline và space.'),('< lowercase.txt','Đọc tệp nguồn qua stdin.'),('> plaintext.txt','Ghi kết quả sang tệp đích mới hoặc ghi đè tệp hiện có.')])
command('tr-map','substitution','Thử một khóa thay thế đơn bảng','Bash · Linux / WSL',"tr 'a-z' 'wjmtxzorvqdukfysnlhipabcge' < plaintext.txt > ciphertext.txt",'Đã có một hoán vị đủ 26 chữ và muốn áp ánh xạ cố định.','a thành w, b thành j,…; ký tự ngoài tập không đổi theo cách dùng này.','Đảo hai tập để giải mã; đây là mã cổ điển không dùng bảo vệ thật.',[
 ('tr','Ánh xạ ký tự theo vị trí tương ứng hai tập.'),("'a-z'",'Bảng chữ bản rõ theo thứ tự.'),("'wjmtxzorvqdukfysnlhipabcge'",'Bảng thay thế gồm 26 ký tự không lặp.'),('< plaintext.txt','Đưa bản rõ vào stdin.'),('> ciphertext.txt','Ghi bản mã ra tệp, có thể ghi đè.')])
command('enc','cbc','Mã hóa CBC bằng mật khẩu trong lab','OpenSSL 3.x', 'openssl enc -aes-256-cbc -salt -pbkdf2 -iter 200000 -in plain.txt -out plain.enc','Học quan hệ giữa password KDF và mã hóa CBC trên tệp thử.','OpenSSL hỏi mật khẩu tương tác và tạo plain.enc theo định dạng enc.','CBC enc không có xác thực. Lệnh lab không là thiết kế lưu trữ hoàn chỉnh.',[
 ('openssl','Bộ công cụ mật mã OpenSSL.'),('enc','Lệnh mã hóa/giải mã đối xứng; không hỗ trợ AEAD theo giao diện này.'),('-aes-256-cbc','Chọn AES khóa 256 bit, khối 128 bit, mode CBC.'),('-salt','Dùng salt cho dẫn xuất khóa từ mật khẩu.'),('-pbkdf2','Chọn PBKDF2 để dẫn xuất vật liệu khóa.'),('-iter 200000','Chọn 200.000 vòng dẫn xuất trong ví dụ; không phải vòng AES.'),('-in plain.txt','Đọc dữ liệu nguồn.'),('-out plain.enc','Ghi tệp mã hóa, có thể ghi đè.')])
command('dec','cbc','Giải mã ví dụ CBC cùng tham số','OpenSSL 3.x','openssl enc -d -aes-256-cbc -pbkdf2 -iter 200000 -in plain.enc -out restored.txt','Cần khôi phục tệp từ ví dụ CBC trước.','Hỏi mật khẩu và ghi restored.txt nếu giải mã/đệm được chấp nhận.','Giải mã không báo lỗi chưa chứng minh tính xác thực; tham số phải khớp.',[
 ('enc','Dùng cùng giao diện mã hóa đối xứng.'),('-d','Chuyển sang giải mã.'),('-aes-256-cbc','Cùng thuật toán và mode của lúc mã hóa.'),('-pbkdf2','Cùng phương pháp dẫn xuất khóa.'),('-iter 200000','Cùng số vòng dẫn xuất; sai có thể tạo khóa/IV sai.'),('-in plain.enc','Tệp bản mã đầu vào.'),('-out restored.txt','Tệp bản rõ kết quả, có thể ghi đè.')])
command('sum','hash-algorithms','Tạo manifest SHA-256 có thể kiểm tra','Bash · GNU coreutils','sha256sum package.bin > package.sha256','Cần lưu digest cùng tên tệp theo định dạng mà công cụ check hiểu.','package.sha256 chứa digest hex và tên tệp.','Manifest cần nguồn xác thực; đối thủ thay cả hai tệp vẫn vượt so hash.',[
 ('sha256sum','Tính SHA-256, xuất theo định dạng GNU checksum.'),('package.bin','Tệp cần băm theo đúng byte.'),('> package.sha256','Chuyển stdout vào manifest, ghi đè nếu đã tồn tại.')])
command('check','hash-apps','Kiểm tra manifest đã tin cậy','Bash · GNU coreutils','sha256sum -c package.sha256','Đã có manifest tin cậy và cần kiểm tệp tải về.','Báo OK/FAILED theo từng tệp trong manifest và mã thoát tương ứng.','Không dùng trực tiếp định dạng openssl dgst mặc định làm manifest GNU.',[
 ('sha256sum','Công cụ tính và kiểm SHA-256.'),('-c','Đọc manifest và so digest của tệp được liệt kê.'),('package.sha256','Tệp manifest có tên tệp và digest đúng định dạng.')])
command('printf-hash','hash-properties','Băm chuỗi không thêm newline','Bash · Linux / WSL',"printf '%s' 'Hello world' | openssl dgst -sha256",'Cần băm chính xác byte Hello world mà không có ký tự xuống dòng.','SHA-256 hex: 64ec88ca00b268e5ba1a35678a1b5316d212f4f366b2477232534a8aeca37f3c.','echo thường thêm newline; cùng chữ nhìn thấy có thể khác byte.',[
 ("printf '%s'",'In đối số theo định dạng chuỗi và không tự thêm newline.'),("'Hello world'",'Chuỗi dữ liệu giữ nguyên nhờ nháy.'),('|','Nối stdout của printf vào stdin của OpenSSL.'),('dgst','Lệnh tính digest, hỗ trợ cả ký/kiểm theo lựa chọn.'),('-sha256','Chọn thuật toán SHA-256.')])
command('hmac-cmd','hmac','Tính HMAC-SHA-256 trên dữ liệu mẫu','Bash · OpenSSL 3.x',"printf '%s' 'My public speech' | openssl dgst -sha256 -hmac 'demo-key'",'Hai bên có chung khóa mẫu và muốn xác thực một thông điệp.','Một HMAC-SHA-256; thay khóa hoặc dữ liệu sẽ đổi tag.','demo-key là dữ liệu giả. Khóa truyền đối số có thể lộ qua lịch sử/tiến trình; không dùng khóa thật.',[
 ("printf '%s'",'Tạo byte đầu vào không newline.'),('|','Đưa byte vào stdin lệnh sau.'),('dgst','Giao diện digest có lựa chọn MAC.'),('-sha256','Chọn hash dùng trong HMAC.'),("-hmac 'demo-key'",'Chọn HMAC với khóa mẫu đã nêu, không phải chỉ H(M).')])
command('genkey','rsa','Sinh khóa RSA thực hành','OpenSSL 3.x','openssl genpkey -algorithm RSA -pkeyopt rsa_keygen_bits:3072 -aes-256-cbc -out private.pem','Cần tạo cặp khóa RSA cho bài tập OAEP/PSS.','Tệp khóa riêng được bảo vệ bằng mật khẩu hỏi tương tác.','Giữ khóa riêng bí mật; chọn tham số theo nhu cầu thực tế. Đây là lệnh hướng dẫn.',[
 ('genpkey','Sinh khóa riêng cho thuật toán được chọn; chứa thông tin để xuất khóa công khai.'),('-algorithm RSA','Chọn thuật toán RSA.'),('-pkeyopt rsa_keygen_bits:3072','Chọn modulus RSA 3072 bit, không phải cỡ khối AES.'),('-aes-256-cbc','Bảo vệ biểu diễn khóa riêng bằng mật khẩu qua cipher được chọn.'),('-out private.pem','Ghi khóa riêng; tránh ghi đè khóa còn cần.')])
command('pubout','rsa','Xuất khóa công khai','OpenSSL 3.x','openssl pkey -in private.pem -pubout -out public.pem','Cần cung cấp phần công khai cho người mã hóa hoặc kiểm chữ ký.','public.pem chứa khóa công khai, không phải khóa riêng.','Xác thực nguồn khóa công khai trước khi tin danh tính gắn với nó.',[
 ('pkey','Xử lý khóa công khai/riêng theo giao diện chung.'),('-in private.pem','Đọc khóa nguồn, có thể hỏi mật khẩu nếu khóa được bảo vệ.'),('-pubout','Chỉ xuất phần khóa công khai.'),('-out public.pem','Tệp khóa công khai kết quả.')])
command('oaep-enc','oaep','Bảo vệ khóa dữ liệu bằng RSA-OAEP','OpenSSL 3.x','openssl pkeyutl -encrypt -pubin -inkey public.pem -in key.bin -out key.enc -pkeyopt rsa_padding_mode:oaep -pkeyopt rsa_oaep_md:sha256 -pkeyopt rsa_mgf1_md:sha256','key.bin là khóa dữ liệu nhỏ, không phải toàn bộ tập tin lớn.','key.enc chứa bản mã OAEP cho người giữ khóa riêng tương ứng.','Tuân giới hạn k−2hLen−2. Ai có public key cũng mã hóa được; không tự xác thực người gửi.',[
 ('pkeyutl','Công cụ thao tác khóa công khai, thay các ví dụ rsautl cũ.'),('-encrypt','Chọn phép mã hóa.'),('-pubin','Đọc khóa đầu vào như khóa công khai.'),('-inkey public.pem','Khóa công khai của người nhận đã được xác minh.'),('-in key.bin','Dữ liệu nhỏ cần mã hóa.'),('-out key.enc','Tệp bản mã đầu ra.'),('-pkeyopt rsa_padding_mode:oaep','Chọn RSA-OAEP thay RSA thô/v1.5.'),('-pkeyopt rsa_oaep_md:sha256','Chọn hash SHA-256 cho OAEP.'),('-pkeyopt rsa_mgf1_md:sha256','Chọn SHA-256 cho MGF1.')])
command('oaep-dec','oaep','Giải mã khóa dữ liệu OAEP','OpenSSL 3.x','openssl pkeyutl -decrypt -inkey private.pem -in key.enc -out key-restored.bin -pkeyopt rsa_padding_mode:oaep -pkeyopt rsa_oaep_md:sha256 -pkeyopt rsa_mgf1_md:sha256','Người nhận cần lấy lại khóa dữ liệu bằng khóa riêng.','key-restored.bin nhận khóa được giải mã nếu mọi điều kiện đúng.','Không lộ chi tiết lỗi giải mã qua giao thức; hai đầu phải thống nhất cả label nếu dùng.',[
 ('-decrypt','Thực hiện giải mã bằng khóa riêng.'),('-inkey private.pem','Khóa riêng của người nhận.'),('-in key.enc','Bản mã OAEP nhận được.'),('-out key-restored.bin','Ghi dữ liệu giải mã, có thể ghi đè.'),('-pkeyopt rsa_padding_mode:oaep','Dùng cùng lược đồ OAEP.'),('-pkeyopt rsa_oaep_md:sha256','Cùng hash OAEP đã dùng khi mã hóa.'),('-pkeyopt rsa_mgf1_md:sha256','Cùng hash cho MGF1.')])
command('pss-sign','pss','Ký thông điệp bằng RSA-PSS','OpenSSL 3.x','openssl dgst -sha256 -sign private.pem -sigopt rsa_padding_mode:pss -sigopt rsa_pss_saltlen:digest -out signature.bin message.txt','Cần tạo chữ ký trên chính xác byte của message.txt.','signature.bin chứa chữ ký, còn message.txt không bị che nội dung.','Chữ ký không tự chống replay; ràng buộc ngữ cảnh giao dịch.',[
 ('dgst','Băm thông điệp rồi thực hiện ký theo lựa chọn.'),('-sha256','Chọn SHA-256 cho digest.'),('-sign private.pem','Dùng khóa riêng tạo chữ ký.'),('-sigopt rsa_padding_mode:pss','Chọn lược đồ chữ ký PSS.'),('-sigopt rsa_pss_saltlen:digest','Độ dài salt bằng độ dài digest.'),('-out signature.bin','Ghi chữ ký nhị phân.'),('message.txt','Tệp có byte được ký.')])
command('pss-verify','pss','Kiểm chứng chữ ký RSA-PSS','OpenSSL 3.x','openssl dgst -sha256 -verify public.pem -signature signature.bin -sigopt rsa_padding_mode:pss -sigopt rsa_pss_saltlen:digest message.txt','Đã có khóa công khai xác thực, thông điệp và chữ ký.','Verified OK hoặc thất bại, cùng mã thoát kiểm chứng.','Thất bại có thể do dữ liệu, khóa, chữ ký hoặc tham số; không tự xác định thủ phạm.',[
 ('-verify public.pem','Dùng khóa công khai đã xác minh để kiểm.'),('-signature signature.bin','Đọc tệp chữ ký cần kiểm.'),('-sha256','Cùng thuật toán hash của lúc ký.'),('-sigopt rsa_padding_mode:pss','Kiểm theo lược đồ PSS.'),('-sigopt rsa_pss_saltlen:digest','Yêu cầu độ dài salt thống nhất ví dụ.'),('message.txt','Byte thông điệp cần kiểm, phải khớp lúc ký.')])
command('ssh-gen','protocols','Sinh khóa SSH cho tài khoản lab','OpenSSH','ssh-keygen -t ed25519 -f ./lab_ed25519 -C study-lab','Cần cặp khóa mới cho môi trường thực hành mà không đè khóa mặc định.','lab_ed25519 là khóa riêng, lab_ed25519.pub là khóa công khai.','Lệnh hỏi passphrase; chỉ phần .pub đi vào authorized_keys. Ed25519 là ví dụ mở rộng, khác ví dụ RSA trong slide.',[
 ('ssh-keygen','Sinh/quản lý khóa OpenSSH.'),('-t ed25519','Chọn loại khóa Ed25519 trong ví dụ mở rộng này.'),('-f ./lab_ed25519','Chọn đường dẫn cơ sở cho cặp khóa, tránh ghi đè khóa mặc định.'),('-C study-lab','Gắn chú thích nhận diện, không phải mật khẩu hay bằng chứng danh tính.')])
command('bmp-header','cbc','Đọc ví dụ giữ header BMP','Bash · Linux / WSL','head -c 54 pic_test.bmp > header.bin','Muốn hiểu thao tác giữ phần đầu của BMP trong minh họa ECB ở slide.','header.bin chứa 54 byte đầu của tệp mẫu.','54 byte chỉ phù hợp giả định BMP mẫu; header/offset thực tế có thể khác.',[
 ('head','Đọc phần đầu dữ liệu.'),('-c 54','Lấy 54 byte, không phải 54 dòng.'),('pic_test.bmp','Tệp BMP mẫu đầu vào.'),('> header.bin','Ghi byte đầu sang tệp mới hoặc ghi đè.')])
command('python-oaep','oaep','Đọc API OAEP của PyCryptodome','Python 3 · cần PyCryptodome',"from Crypto.Cipher import PKCS1_OAEP\nfrom Crypto.Hash import SHA256\nfrom Crypto.PublicKey import RSA\nkey = RSA.import_key(open('public.pem', 'rb').read())\ncipher = PKCS1_OAEP.new(key, hashAlgo=SHA256)\nciphertext = cipher.encrypt(b'lab session key')",'Phân biệt import khóa, chọn lược đồ và thao tác mã hóa trong đoạn chương trình.','ciphertext là bytes mã hóa OAEP; không có bước chạy chương trình trong web.','Đầu vào phải trong giới hạn OAEP; phần ví dụ dùng dữ liệu giả, mã hóa không chứng minh nguồn.',[
 ('RSA.import_key(...)','Đọc và phân tích biểu diễn khóa thành đối tượng RSA.'),("open('public.pem', 'rb').read()",'Đọc byte của tệp công khai; rb là chế độ nhị phân.'),('PKCS1_OAEP.new(key, hashAlgo=SHA256)','Tạo đối tượng OAEP với khóa và hash đã chọn; mặc định MGF theo cấu hình thư viện.'),("b'lab session key'",'Literal bytes đầu vào thay cho chuỗi Unicode.'),('cipher.encrypt(...)','Mã hóa bằng lược đồ OAEP, không dùng RSA thô.')])
